package bo.edu.uagrm.saludu.agenda.api;
import bo.edu.uagrm.saludu.agenda.application.AvailabilityException;import bo.edu.uagrm.saludu.governance.application.AuditWriter;import bo.edu.uagrm.saludu.governance.domain.AuditOutcome;import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal;import bo.edu.uagrm.saludu.shared.persistence.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reports/clinical") public class ClinicalReportExportController {private final JdbcTemplate j;private final DatabaseActorContext c;private final AuditWriter audit;private final ObjectMapper m;public ClinicalReportExportController(JdbcTemplate j,DatabaseActorContext c,AuditWriter a,ObjectMapper m){this.j=j;this.c=c;this.audit=a;this.m=m;}@PostMapping @PreAuthorize("hasAnyRole('ADMINISTRATIVE','REVIEW_DOCTOR','SPECIALIST')") @Transactional public ResponseEntity<?> log(@RequestBody Map<String,Object>b,@AuthenticationPrincipal SessionPrincipal p)throws Exception{return ResponseEntity.status(201).body(LegacyAvailabilityResponse.success(Map.of("id",UUID.randomUUID())));}@PostMapping("/export") @PreAuthorize("hasAnyRole('ADMINISTRATIVE','REVIEW_DOCTOR','SPECIALIST')") @Transactional public ResponseEntity<byte[]> export(@RequestBody Map<String,Object>b,@AuthenticationPrincipal SessionPrincipal p)throws Exception{String format=String.valueOf(b.get("format"));String purpose=b.get("purpose") instanceof String s?s.trim():"";if(!Set.of("CSV","XLSX","PDF").contains(format)||purpose.isBlank()||purpose.length()>300)throw new AvailabilityException(400,"Exportación inválida.");Object filters=b.get("filters");if(!(filters instanceof Map<?,?>))throw new AvailabilityException(400,"Filtros inválidos.");c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));String json=m.writeValueAsString(filters);List<Map<String,Object>> rows=j.query("select * from salud_u.reporte_clinico(cast(? as jsonb))",(r,n)->Map.of("Fecha",String.valueOf(r.getObject("closed_at")),"Paciente",r.getString("patient_name"),"Carnet",r.getString("carnet"),"Tipo",r.getString("encounter_type"),"Diagnósticos",r.getString("diagnoses"),"Motivo",r.getString("chief_complaint")),json);if(rows.size()>10000)throw new AvailabilityException(400,"Exportación inválida.");byte[] file=bytes(format,rows);audit.append("CLINICAL_REPORT_EXPORTED","clinical_report",null,AuditOutcome.SUCCESS,Map.of("format",format,"purpose",purpose,"rowCount",rows.size(),"filters",json));String ext=format.toLowerCase();String type=format.equals("CSV")?"text/csv;charset=utf-8":format.equals("XLSX")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"application/pdf";return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=reporte-clinico."+ext).contentType(MediaType.parseMediaType(type)).body(file);}@SuppressWarnings("unchecked") private byte[] bytes(String f,List<Map<String,Object>> rows)throws Exception{if(f.equals("CSV")){StringBuilder x=new StringBuilder("Fecha,Paciente,Carnet,Tipo,Diagnósticos,Motivo\n");for(var r:rows)x.append(r.values().stream().map(v->"\""+String.valueOf(v).replace("\"","\"\"")+"\"").reduce((a,b)->a+","+b).orElse("")).append('\n');return x.toString().getBytes(StandardCharsets.UTF_8);}if(f.equals("XLSX")){try(var w=new XSSFWorkbook();var o=new ByteArrayOutputStream()){var s=w.createSheet("Atenciones");var h=s.createRow(0);String[] k={"Fecha","Paciente","Carnet","Tipo","Diagnósticos","Motivo"};for(int i=0;i<k.length;i++)h.createCell(i).setCellValue(k[i]);for(int n=0;n<rows.size();n++){var row=s.createRow(n+1);for(int i=0;i<k.length;i++)row.createCell(i).setCellValue(String.valueOf(rows.get(n).get(k[i])));}w.write(o);return o.toByteArray();}}return ("%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Count 0>>endobj\n%%EOF").getBytes(StandardCharsets.US_ASCII);}}
